Чтобы создать бота Discord с одной командой бан, используйте следующие шаги:

1. Сначала, установите Discord.js v14 и другие зависимости, если вы этого еще не сделали:

   ```
   npm install discord.js @discordjs/rest discord.js-commando
   ```

2. Создайте файл `config.json` и вставьте в него следующие настройки:

   ```json
   {
     "token": "YOUR_DISCORD_BOT_TOKEN",
     "clientID": "YOUR_CLIENT_ID",
     "guildID": "YOUR_GUILD_ID"
   }
   ```

   - `YOUR_DISCORD_BOT_TOKEN`: Вставьте токен вашего Discord бота в эту строку.
   - `YOUR_CLIENT_ID`: Вставьте ID клиента вашего Discord бота в эту строку.
   - `YOUR_GUILD_ID`: Вставьте ID сервера Discord, на котором будет работать ваш бот в эту строку.

3. Создайте новый файл `index.js` и вставьте в него следующий код:

   ```javascript
   const { Client, GatewayIntentBits } = require("discord.js");
   const { REST } = require("@discordjs/rest");

   const fs = require("fs");

   const { clientId, guildId, token } = require("./config.json");

   const commands = [];
   const commandFiles = fs.readdirSync("./commands").filter(file => file.endsWith(".js"));

   for (const file of commandFiles) {
     const command = require(`./commands/${file}`);
     commands.push(command.data);
   }

   const rest = new REST({ version: "14" }).setToken(token);

   async function registerCommands() {
     try {
       if (process.env.NODE_ENV !== "production") {
         await rest.put(
           `https://discord.com/api/v${process.env.VITE_DISCORDJS_VERSION}/guilds/${guildId}/commands`,
           { body: commands }
         );
       } else {
         await rest.put(
           `https://discord.com/api/v${process.env.VITE_DISCORDJS_VERSION}/apps/${clientId}/guilds/${guildId}/commands`,
           { body: commands }
         );
       }
       console.log("Successfully registered application commands.");
     } catch (error) {
       console.error(error);
     }
   }

   async function main() {
     const client = new Client({
       intents: [
         GatewayIntentBits.Guilds,
         GatewayIntentBits.GuildMessages,
         GatewayIntentBits.MessageContent,
       ],
     });

     client.on("ready", () => {
       console.log("Bot is ready!");
     });

     client.on("interactionCreate", async interaction => {
       if (!interaction.isChatInputCommand()) return;

       const command = commands.find(c => c.name === interaction.commandName);

       try {
         await command.execute(interaction);
       } catch (error) {
         console.error(error);
         await interaction.reply({ content: "There was an error while executing this command!", ephemeral: true });
       }
     });

     await registerCommands();

     client.login(token);
   }

   main();
   ```

   - В данном примере, мы используем `Commando` библиотеку, поэтому нам нужен `commando.js`. Если вы хотите использовать другие библиотеки, необходимо изменить код в соответствии с вашей библиотекой.

4. Создайте новый файл `commandBan.js` в папке `./commands` и вставьте в него следующий код:

   ```javascript
   const { SlashCommandBuilder } = require("@discordjs/builders");

   module.exports = {
     data: new SlashCommandBuilder()
       .setName("ban")
       .setDescription("Bans the specified user from the server.")
       .addUserOption(option =>
         option.setName("user")
           .setDescription("The user to ban.")
           .setRequired(true)),
     async execute(interaction) {
       const user = interaction.options.getUser("user");

       await interaction.guild.members.ban(user, { days: 7, reason: "Banned by command" });

       await interaction.reply(`Successfully banned ${user.tag}`);
     },
   };
   ```

   - Замените `7` на число дней, на которое вы хотите банить пользователя.

5. В файле `package.json`, добавьте следующую секцию:

   ```json
   "scripts": {
     "start": "node index.js"
   },
   ```

6. Выполните команду `npm start` в консоли, чтобы запустить бота.

С этим кодом, ваш бот сможет использовать команду бан в вашем Discord сервере. Обратите внимание, что вам необходимо создать и настроить канал логирования, чтобы отслеживать ошибки и другие события, связанные с вашим ботом.

To create a high-quality testing environment in Cypress with Docker, and enable Cypress to take screenshots and save them, follow these steps:

