       its.content = its.readAssets(file.path).content;
     });

     addPlugin(require("cypress-docker-plugins/plugin"));
   };
   ```

10. Add the following Cypress configuration to your `cypress.json` file:

   ```
   {
     "baseUrl": "http://localhost:8080",
     "reporterEnabled": "mochawesome",
     "reporterOptions": {
       "reportDir": "cypress/reports",
       "overwrite": false,
       "json": true,
       "html": true,
       "cliReport": false
     },
     "experimentalInteractiveRun": true,
     "chromeWebSecurity": false,
     "pluginsFile": "cypress/plugins/index.js",
     "screenshotOnRunFailure": true,
     "viewportPreferred": "macbook-13-inch",
     "viewportPresets": ["macbook-13-inch"],
     "video": false,
     "fixturesFolder": "cypress/fixtures",
     "integrationFolder": "cypress/integration",
     "supportFile": "cypress/support/commands.js",
     "pageLoadTimeout": 60000,
     "responseTimeout": 30000,
     "watchForFileChanges": true
   }
   ```

11. Create a new directory named `cypress` in the root of your project.

12. Inside the `cypress` directory, create a new directory named `fixtures`.

13. Inside the `cypress` directory, create a new directory named `integration`.

14. Inside the `cypress` directory, create a new file named `commands.js` in the `support` directory.

15. In the `commands.js` file, add the following content:

   ```
   import { addMethod } from "cypress-xpath";

   addMethod("containsXpath", (subject, xpath) => {
     const $el = Cypress.$(subject);
     return $el.filter(function() {
       return this.matches(xpath);
     });
   });

   Cypress.Commands.add("getByXpath", { prevSubject: true }, (subject, xpath) => {
     return subject.containsXpath(xpath).should("be.visible");
   });
