   module.exports = defineConfig({
     video: false,
     screenshotOnRunFailure: true,
     screenshotFolder: "cypress/screenshots",
     videoUploadOnPasses: true,
     videoUploadOnFailures: true,
     viewportWidth: 1280,
     viewportHeight: 720,
